CREATE OR REFRESH STREAMING TABLE events;

-- one append flow per source, no UNION needed
CREATE FLOW kafka_eu AS INSERT INTO events BY NAME
SELECT * FROM STREAM read_kafka(
  bootstrapServers => 'broker:9092', subscribe => 'events_eu');

CREATE FLOW kafka_us AS INSERT INTO events BY NAME
SELECT * FROM STREAM read_kafka(
  bootstrapServers => 'broker:9092', subscribe => 'events_us');

-- one-time backfill, re-runs only on full refresh
CREATE FLOW backfill_2025 AS INSERT ONCE INTO events BY NAME
SELECT * FROM read_files('/Volumes/main/archive/events_2025/', format => 'parquet');
